CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261101205948_InitialCreate') THEN
    CREATE TABLE categories (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(80) NOT NULL,
        "Description" character varying(250),
        CONSTRAINT "PK_categories" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261101205948_InitialCreate') THEN
    CREATE TABLE customers (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "DocType" character varying(10) NOT NULL,
        "DocNumber" character varying(11) NOT NULL,
        "Name" character varying(200) NOT NULL,
        "Email" character varying(150),
        "Phone" character varying(20),
        "Address" character varying(250),
        "CreatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_customers" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261101205948_InitialCreate') THEN
    CREATE TABLE document_series (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "DocumentType" character varying(20) NOT NULL,
        "Code" character varying(4) NOT NULL,
        "LastNumber" integer NOT NULL,
        "IsActive" boolean NOT NULL,
        CONSTRAINT "PK_document_series" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261101205948_InitialCreate') THEN
    CREATE TABLE users (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Email" character varying(150) NOT NULL,
        "FullName" character varying(120) NOT NULL,
        "PasswordHash" character varying(200) NOT NULL,
        "Role" character varying(20) NOT NULL,
        "IsActive" boolean NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_users" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261101205948_InitialCreate') THEN
    CREATE TABLE products (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Sku" character varying(30) NOT NULL,
        "Name" character varying(150) NOT NULL,
        "CategoryId" integer NOT NULL,
        "Price" numeric(12,2) NOT NULL,
        "Stock" integer NOT NULL,
        "MinStock" integer NOT NULL,
        "IsActive" boolean NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_products" PRIMARY KEY ("Id"),
        CONSTRAINT ck_products_price_positive CHECK ("Price" > 0),
        CONSTRAINT ck_products_stock_non_negative CHECK ("Stock" >= 0),
        CONSTRAINT "FK_products_categories_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES categories ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261101205948_InitialCreate') THEN
    CREATE TABLE cash_sessions (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "CashierId" integer NOT NULL,
        "Status" character varying(20) NOT NULL,
        "OpenedAt" timestamp with time zone NOT NULL,
        "ClosedAt" timestamp with time zone,
        "OpeningAmount" numeric(12,2) NOT NULL,
        "ExpectedCash" numeric(12,2),
        "CountedCash" numeric(12,2),
        "Difference" numeric(12,2),
        "Notes" character varying(500),
        CONSTRAINT "PK_cash_sessions" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_cash_sessions_users_CashierId" FOREIGN KEY ("CashierId") REFERENCES users ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261101205948_InitialCreate') THEN
    CREATE TABLE sales (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "DocumentType" character varying(20) NOT NULL,
        "Series" character varying(4) NOT NULL,
        "Number" integer NOT NULL,
        "CustomerId" integer,
        "CashierId" integer NOT NULL,
        "CashSessionId" integer NOT NULL,
        "GrossAmount" numeric(12,2) NOT NULL,
        "Discount" numeric(12,2) NOT NULL,
        "Subtotal" numeric(12,2) NOT NULL,
        "Igv" numeric(12,2) NOT NULL,
        "Total" numeric(12,2) NOT NULL,
        "AmountPaid" numeric(12,2) NOT NULL,
        "Change" numeric(12,2) NOT NULL,
        "Status" character varying(20) NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        "VoidedAt" timestamp with time zone,
        "VoidedById" integer,
        "VoidReason" character varying(250),
        CONSTRAINT "PK_sales" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_sales_cash_sessions_CashSessionId" FOREIGN KEY ("CashSessionId") REFERENCES cash_sessions ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_sales_customers_CustomerId" FOREIGN KEY ("CustomerId") REFERENCES customers ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_sales_users_CashierId" FOREIGN KEY ("CashierId") REFERENCES users ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_sales_users_VoidedById" FOREIGN KEY ("VoidedById") REFERENCES users ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261101205948_InitialCreate') THEN
    CREATE TABLE payments (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "SaleId" integer NOT NULL,
        "Method" character varying(20) NOT NULL,
        "Amount" numeric(12,2) NOT NULL,
        "Reference" character varying(60),
        CONSTRAINT "PK_payments" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_payments_sales_SaleId" FOREIGN KEY ("SaleId") REFERENCES sales ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261101205948_InitialCreate') THEN
    CREATE TABLE sale_items (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "SaleId" integer NOT NULL,
        "ProductId" integer NOT NULL,
        "ProductName" character varying(150) NOT NULL,
        "Quantity" integer NOT NULL,
        "UnitPrice" numeric(12,2) NOT NULL,
        "LineTotal" numeric(12,2) NOT NULL,
        CONSTRAINT "PK_sale_items" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_sale_items_products_ProductId" FOREIGN KEY ("ProductId") REFERENCES products ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_sale_items_sales_SaleId" FOREIGN KEY ("SaleId") REFERENCES sales ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

